//! `lunepack publish` end to end, through the binary only: `init`, twelve publishes of two targets
//! over two channels with `keep = 10`, `refresh`, a store laid out by the old scripts, and every
//! refusal checked by its message. The store is a `--store-dir`; `fetch` reads the public side of
//! the same directory through a loopback HTTP server, and one run goes through the
//! signature-checking fake S3 so the credentials really flow through the environment.
//!
//! Keys are generated by the binary at test time and the store credentials are made up at test
//! time. Every output of every run is scanned for the throwaway secret, the access key and
//! `-----BEGIN`; the positive control proves the scan catches a planted line. Failure injection,
//! the race and the mutation tests live in the unit tests of `src/cmd_publish`.
//!
//! Failure lines name the version, the command or the store path, never a document's bytes.

mod common;
#[path = "common/publish.rs"]
mod publish;

use std::collections::BTreeMap;
use std::fs;
use std::io::{Read, Write};
use std::net::{Ipv4Addr, SocketAddr, TcpListener, TcpStream};
use std::path::{Path, PathBuf};
use std::process::Output;
use std::sync::Arc;
use std::sync::atomic::{AtomicBool, Ordering};
use std::thread::{self, JoinHandle};
use std::time::Duration;

use common::*;
use lunepack_testkit::{FakeS3Config, FakeS3Server};
use publish::*;

const PENDING: &str = "lunepack-pending-deletes.json";
const EMPTY_RECORD: &[u8] = b"{\"format\":1,\"keys\":[],\"uploading\":[]}\n";

fn targets() -> [&'static str; 2] {
    if cfg!(windows) {
        ["windows-x86_64", "windows-aarch64"]
    } else {
        ["linux-x86_64", "linux-aarch64"]
    }
}

// --- the public side of the store, over HTTP ------------------------------------------------------

/// Serves the files of a directory under `/hello/`; stops on drop.
struct Server {
    addr: SocketAddr,
    stop: Arc<AtomicBool>,
    handle: Option<JoinHandle<()>>,
}

impl Server {
    fn start(root: &Path) -> Server {
        let listener = TcpListener::bind((Ipv4Addr::LOCALHOST, 0)).expect("bind");
        let addr = listener.local_addr().expect("addr");
        let stop = Arc::new(AtomicBool::new(false));
        let handle = {
            let (stop, root) = (stop.clone(), root.to_owned());
            thread::spawn(move || {
                for stream in listener.incoming() {
                    if stop.load(Ordering::SeqCst) {
                        return;
                    }
                    if let Ok(stream) = stream {
                        serve(stream, &root);
                    }
                }
            })
        };
        Server {
            addr,
            stop,
            handle: Some(handle),
        }
    }

    fn feed_url(&self) -> String {
        format!("http://{}/hello/", self.addr)
    }
}

impl Drop for Server {
    fn drop(&mut self) {
        self.stop.store(true, Ordering::SeqCst);
        let _ = TcpStream::connect_timeout(&self.addr, Duration::from_millis(200));
        if let Some(handle) = self.handle.take() {
            let _ = handle.join();
        }
    }
}

fn serve(mut stream: TcpStream, root: &Path) {
    let _ = stream.set_read_timeout(Some(Duration::from_secs(5)));
    let mut head = Vec::new();
    let mut chunk = [0u8; 1024];
    while !head.windows(4).any(|w| w == b"\r\n\r\n") && head.len() < 16 * 1024 {
        match stream.read(&mut chunk) {
            Ok(0) | Err(_) => return,
            Ok(n) => head.extend_from_slice(&chunk[..n]),
        }
    }
    let text = String::from_utf8_lossy(&head).into_owned();
    let target = text
        .lines()
        .next()
        .and_then(|l| l.split(' ').nth(1))
        .unwrap_or("/");
    let rel = target.strip_prefix("/hello/").unwrap_or("");
    let found = if !rel.is_empty() && !rel.contains("..") {
        fs::read(root.join(rel)).ok()
    } else {
        None
    };
    let (status, body) = match found {
        Some(bytes) => (200, bytes),
        None => (404, Vec::new()),
    };
    let reply = format!(
        "HTTP/1.1 {status} X\r\nContent-Length: {}\r\nConnection: close\r\n\r\n",
        body.len()
    );
    let _ = stream.write_all(reply.as_bytes());
    let _ = stream.write_all(&body);
    let _ = stream.flush();
    let _ = stream.shutdown(std::net::Shutdown::Write);
}

// --- the site --------------------------------------------------------------------------------------

/// A fixture, a store directory with a sibling prefix, the server over its public side, and the
/// app's config.
struct Site {
    f: Fixture,
    origin: PathBuf,
    store: PathBuf,
    config: PathBuf,
    access: String,
    secret: String,
    _server: Server,
}

fn copy_tree(from: &Path, to: &Path) {
    for (rel, bytes) in tree(from) {
        let dest = to.join(rel);
        fs::create_dir_all(dest.parent().unwrap()).unwrap();
        fs::write(dest, bytes).unwrap();
    }
}

impl Site {
    /// The store holds only a sibling prefix `other/`; nothing of the app yet. Config: two
    /// channels, pre-releases to beta only, `keep` releases kept.
    fn bare(keep: u32) -> Site {
        let (mut f, origin) = Fixture::new(now() - 3600);
        let access = made_up("AKID", 20);
        let secret = made_up("SECRET", 40);
        f.secrets.push(access.clone().into_bytes());
        f.secrets.push(secret.clone().into_bytes());
        f.secrets.push(b"-----BEGIN".to_vec());
        let store = f.dir.path().join("store");
        for (rel, bytes) in [
            ("public/other/keys.json", &b"{\"other\":1}"[..]),
            ("public/other/feed-stable.json", b"{\"other\":2}"),
            ("public/other/1.0.0/x.pack", b"other pack bytes"),
            ("private/other/lunepack-state.json", b"{\"other\":3}"),
            (
                "private/other/lunepack-pending-deletes.json",
                b"{\"other\":4}",
            ),
        ] {
            let path = store.join(rel);
            fs::create_dir_all(path.parent().unwrap()).unwrap();
            fs::write(path, bytes).unwrap();
        }
        let server = Server::start(&store.join("public").join(P));
        let mut site = Site {
            config: PathBuf::new(),
            f,
            origin,
            store,
            access,
            secret,
            _server: server,
        };
        site.config = site.app_config(
            keep,
            "store = \"r2\"\naccount_id_env = \"HELLO_R2_ACCOUNT_ID\"",
        );
        site
    }

    /// `bare`, then `publish init` from the fixture's release directory.
    fn new(keep: u32) -> Site {
        let site = Site::bare(keep);
        let out = site.cmd("init", &["--release-dir", s(&site.origin)]);
        assert_ok(&out, "init");
        site
    }

    fn app_config(&self, keep: u32, store: &str) -> PathBuf {
        let mut text = fs::read_to_string(&self.f.pack_config).unwrap();
        text.push_str(&format!(
            "\n[update]\nfeed = \"{}\"\n\n[install]\nentry = \"bin/app\"\nname = \"Hello\"\n\n\
             [publish]\nprefix = \"{P}\"\n{store}\naccess_key_env = \"HELLO_STORE_KEY\"\nsecret_key_env = \"HELLO_STORE_SECRET\"\n\
             public_bucket = \"hello-public\"\nprivate_bucket = \"hello-private\"\nkeep = {keep}\n\
             channels = [\"stable\", \"beta\"]\nprerelease_channels = [\"beta\"]\n",
            self._server.feed_url()
        ));
        let path = self
            .f
            .dir
            .path()
            .join(format!("app-{}-{keep}.toml", text.len()));
        fs::write(&path, text).unwrap();
        path
    }

    fn sign(&self) -> String {
        format!("file:{}", s(&self.f.release_signer))
    }

    /// `publish <command> <args> --store-dir <store>`, without `SOURCE_DATE_EPOCH`.
    fn cmd(&self, command: &str, args: &[&str]) -> Output {
        let mut all = vec!["--config", s(&self.config), "publish", command];
        all.extend_from_slice(args);
        all.extend_from_slice(&["--store-dir", s(&self.store)]);
        self.f.run_plain(&all, &[])
    }

    /// `publish fetch` (it reads the public feed over HTTP and takes no store).
    fn fetch(&self, rd: &Path, version: &str) -> Output {
        self.f.run_plain(
            &[
                "--config",
                s(&self.config),
                "publish",
                "fetch",
                "--release-dir",
                s(rd),
                "--version",
                version,
            ],
            &[],
        )
    }

    fn refresh(&self, extra: &[&str]) -> Output {
        let sign = self.sign();
        let mut args = vec!["--sign", sign.as_str()];
        args.extend_from_slice(extra);
        self.cmd("refresh", &args)
    }

    fn plan(&self) -> String {
        let out = self.cmd("plan", &[]);
        assert_ok(&out, "plan");
        stdout(&out)
    }

    /// Packs `version` for `target` into `rd`, as the pack job does (with `SOURCE_DATE_EPOCH`).
    fn pack(&self, rd: &Path, version: &str, target: &str) {
        let input = self.f.dir.path().join(format!("input-{version}"));
        if !input.exists() {
            fs::create_dir_all(input.join("bin")).unwrap();
            fs::write(
                input.join("bin/app"),
                format!("app {version}\n").repeat(400),
            )
            .unwrap();
            fs::write(input.join("readme.txt"), format!("readme of {version}\n")).unwrap();
        }
        let sign = self.sign();
        let out = self.f.run(
            &[
                "--config",
                s(&self.f.pack_config),
                "pack",
                "--input",
                s(&input),
                "--version",
                version,
                "--target",
                target,
                "--release-dir",
                s(rd),
                "--sign",
                &sign,
            ],
            &[],
        );
        assert_ok(&out, &format!("pack {version} {target}"));
    }

    /// `fetch`, a pack of both targets, and the release directory.
    fn prepare(&self, version: &str) -> PathBuf {
        let rd = self.f.dir.path().join(format!("rd-{version}"));
        let out = self.fetch(&rd, version);
        assert_ok(&out, &format!("fetch {version}"));
        for target in targets() {
            self.pack(&rd, version, target);
        }
        rd
    }

    fn push_out(&self, rd: &Path, version: &str, extra: &[&str]) -> Output {
        let both = targets().join(",");
        let mut args = vec!["--store-dir", s(&self.store), "--require-targets", &both];
        args.extend_from_slice(extra);
        self.f.push(&self.config, rd, version, &args, &[])
    }

    /// One ordinary publish: fetch, pack both targets, push; the sibling prefix stays as it was.
    fn publish(&self, version: &str) {
        let rd = self.prepare(version);
        let out = self.push_out(&rd, version, &[]);
        assert_ok(&out, &format!("push {version}"));
        self.assert_sibling();
    }

    fn sibling(&self) -> BTreeMap<String, Vec<u8>> {
        let mut all = BTreeMap::new();
        for side in ["public", "private"] {
            for (rel, bytes) in tree(&self.store.join(side).join("other")) {
                all.insert(format!("{side}/{rel}"), bytes);
            }
        }
        all
    }

    fn assert_sibling(&self) {
        let sibling = self.sibling();
        assert_eq!(
            sibling.keys().collect::<Vec<_>>(),
            [
                "private/lunepack-pending-deletes.json",
                "private/lunepack-state.json",
                "public/1.0.0/x.pack",
                "public/feed-stable.json",
                "public/keys.json"
            ],
            "the sibling prefix gained or lost an object"
        );
        assert_eq!(sibling["public/keys.json"], b"{\"other\":1}");
        assert_eq!(sibling["public/feed-stable.json"], b"{\"other\":2}");
        assert_eq!(sibling["public/1.0.0/x.pack"], b"other pack bytes");
        assert_eq!(sibling["private/lunepack-state.json"], b"{\"other\":3}");
        assert_eq!(
            sibling["private/lunepack-pending-deletes.json"],
            b"{\"other\":4}"
        );
    }

    fn public(&self) -> BTreeMap<String, Vec<u8>> {
        tree(&self.store.join("public").join(P))
    }

    fn private(&self) -> BTreeMap<String, Vec<u8>> {
        tree(&self.store.join("private").join(P))
    }

    /// The version folders that hold objects in the public side.
    fn folders(&self) -> Vec<String> {
        let mut out: Vec<String> = self
            .public()
            .keys()
            .filter_map(|k| k.split_once('/').map(|(v, _)| v.to_owned()))
            .collect();
        out.dedup();
        out
    }

    /// `verify` on a download of the public side: every listed document and object checks.
    fn assert_verifies(&self, name: &str) {
        let dir = self.f.dir.path().join(name);
        copy_tree(&self.store.join("public").join(P), &dir);
        let out = self.f.run_plain(
            &["--config", s(&self.f.pack_config), "verify", s(&dir)],
            &[],
        );
        assert_ok(&out, "verify a download of the store");
    }
}

/// The versions `plan` shows in the feed of `channel`, newest first.
fn listed(plan: &str, channel: &str) -> Vec<String> {
    let line = plan
        .lines()
        .find(|l| l.starts_with(&format!("feed-{channel}.json: ")))
        .unwrap_or_else(|| panic!("no feed-{channel}.json line in the plan"));
    let (_, versions) = line
        .split_once("release(s): ")
        .unwrap_or_else(|| panic!("no release list in the feed-{channel}.json line"));
    versions.split(", ").map(str::to_owned).collect()
}

fn feed_seq(plan: &str, channel: &str) -> u64 {
    let line = plan
        .lines()
        .find(|l| l.starts_with(&format!("feed-{channel}.json: seq ")))
        .unwrap();
    line.split("seq ")
        .nth(1)
        .unwrap()
        .split(',')
        .next()
        .unwrap()
        .parse()
        .unwrap()
}

fn newest(from: u32, to: u32) -> Vec<String> {
    (from..=to).rev().map(|m| format!("1.{m}.0")).collect()
}

// --- the scenarios ---------------------------------------------------------------------------------

#[test]
fn twelve_publishes_over_two_channels_keep_the_ten_newest_and_purge_the_rest() {
    let site = Site::new(10);
    site.assert_sibling();
    // The first publish after init: init wrote keys.json and the state, nothing else.
    assert_eq!(
        site.public().keys().collect::<Vec<_>>(),
        ["keys.json"],
        "init wrote more than keys.json"
    );

    // 1.0.0 .. 1.11.0: by text 1.10.0 and 1.11.0 sort below 1.2.0; by precedence they are newest.
    for minor in 0..=11 {
        site.publish(&format!("1.{minor}.0"));
    }
    let plan = site.plan();
    for channel in ["stable", "beta"] {
        assert_eq!(listed(&plan, channel), newest(2, 11), "feed-{channel}.json");
    }
    assert!(plan.contains("pending deletes: none"), "{plan}");

    // The dropped versions' objects are gone, the retained ones are all there, and the record is
    // empty.
    assert_eq!(
        site.folders()
            .iter()
            .cloned()
            .collect::<std::collections::BTreeSet<_>>(),
        newest(2, 11).into_iter().collect()
    );
    let public = site.public();
    for version in newest(2, 11) {
        for target in targets() {
            for ext in ["pack", "manifest.json"] {
                assert!(
                    public.contains_key(&format!("{version}/{target}.{ext}")),
                    "{version}/{target}.{ext} is missing"
                );
            }
        }
    }
    assert!(
        public
            .keys()
            .all(|k| !k.starts_with("1.0.0/") && !k.starts_with("1.1.0/")),
        "an object of a dropped version is still there"
    );
    assert_eq!(site.private()[PENDING], EMPTY_RECORD);
    site.assert_verifies("download-12");

    // A pre-release goes to beta only: beta drops 1.2.0, stable still lists it, so its folder
    // stays.
    site.publish("1.12.0-rc.1");
    let plan = site.plan();
    assert_eq!(listed(&plan, "stable"), newest(2, 11));
    let mut beta = vec!["1.12.0-rc.1".to_owned()];
    beta.extend(newest(3, 11));
    assert_eq!(listed(&plan, "beta"), beta);
    assert!(
        site.public()
            .contains_key(&format!("1.2.0/{}.pack", targets()[0]))
    );
    assert_eq!(site.private()[PENDING], EMPTY_RECORD);
    site.assert_verifies("download-13");

    // A refresh with nothing expiring writes nothing; a full refresh raises both seqs and keeps
    // every release.
    let (before_public, before_private) = (site.public(), site.private());
    let out = site.refresh(&["--if-expiring-within-days", "7"]);
    assert_ok(&out, "refresh, nothing due");
    assert!(
        stdout(&out).contains("nothing to refresh"),
        "{}",
        stdout(&out)
    );
    assert!(site.public() == before_public && site.private() == before_private);
    let seqs = (feed_seq(&plan, "stable"), feed_seq(&plan, "beta"));
    let out = site.refresh(&[]);
    assert_ok(&out, "refresh");
    assert!(
        stdout(&out).contains("refreshed: 2 feed(s)"),
        "{}",
        stdout(&out)
    );
    let after = site.plan();
    assert_eq!(listed(&after, "stable"), newest(2, 11));
    assert_eq!(listed(&after, "beta"), beta);
    assert!(feed_seq(&after, "stable") > seqs.0 && feed_seq(&after, "beta") > seqs.1);
    let moved: Vec<String> = site
        .public()
        .iter()
        .filter(|(k, v)| before_public.get(*k) != Some(*v))
        .map(|(k, _)| k.clone())
        .collect();
    assert_eq!(moved, ["feed-beta.json", "feed-stable.json"]);
    site.assert_verifies("download-refreshed");
    site.assert_sibling();

    // The same store through the signature-checking fake S3: plan and refresh with the credentials
    // in the environment; nothing printed holds them (every run's output is scanned).
    let server = FakeS3Server::start(FakeS3Config::new(
        &["hello-public", "hello-private"],
        "us-east-1",
        &site.access,
        &site.secret,
        Arc::new(lunepack::SystemClock),
    ))
    .unwrap();
    for (rel, bytes) in site.public() {
        server.seed("hello-public", &format!("{P}/{rel}"), &bytes);
    }
    for (rel, bytes) in site.private() {
        server.seed("hello-private", &format!("{P}/{rel}"), &bytes);
    }
    let s3 = site.app_config(
        10,
        "store = \"s3\"\nendpoint_env = \"HELLO_S3_ENDPOINT\"\nregion = \"us-east-1\"",
    );
    let endpoint = server.endpoint();
    let env = [
        ("HELLO_S3_ENDPOINT", endpoint.as_str()),
        ("HELLO_STORE_KEY", site.access.as_str()),
        ("HELLO_STORE_SECRET", site.secret.as_str()),
    ];
    let out = site
        .f
        .run_plain(&["--config", s(&s3), "publish", "plan"], &env);
    assert_ok(&out, "plan over S3");
    assert_eq!(listed(&stdout(&out), "stable"), newest(2, 11));
    let sign = site.sign();
    let out = site.f.run_plain(
        &["--config", s(&s3), "publish", "refresh", "--sign", &sign],
        &env,
    );
    assert_ok(&out, "refresh over S3");
    assert!(
        server.object("hello-public", &format!("{P}/feed-stable.json"))
            != site.public().get("feed-stable.json").cloned(),
        "the S3 refresh did not write the feed"
    );
    assert!(server.requests().iter().all(|r| r.status != 403));
}

#[test]
fn a_store_laid_out_by_the_old_scripts_is_published_into_without_init() {
    let site = Site::bare(10);
    let f = &site.f;
    // The old script's layout, made with the CLI's own commands: keys.json, a feed, a version
    // folder, and the state file in the private side. No pending record, no init.
    site.pack(&site.origin, "1.0.0", targets()[0]);
    let sign = site.sign();
    let out = f.run(
        &[
            "--config",
            s(&f.pack_config),
            "feed",
            "add",
            "--release-dir",
            s(&site.origin),
            "--channel",
            "stable",
            "--version",
            "1.0.0",
            "--sign",
            &sign,
        ],
        &[],
    );
    assert_ok(&out, "feed add");
    copy_tree(&site.origin, &site.store.join("public").join(P));
    fs::create_dir_all(site.store.join("private").join(P)).unwrap();
    fs::write(
        site.store
            .join("private")
            .join(P)
            .join("lunepack-state.json"),
        f.state(),
    )
    .unwrap();
    assert!(!site.private().contains_key(PENDING));
    let old = site.public();
    assert!(old.contains_key("keys.json") && old.contains_key("feed-stable.json"));
    site.assert_sibling();

    let plan = site.plan();
    assert_eq!(listed(&plan, "stable"), ["1.0.0"]);
    // One target only was published before; the release now has two, and the push needs no init.
    site.publish("1.1.0");
    let plan = site.plan();
    assert_eq!(listed(&plan, "stable"), ["1.1.0", "1.0.0"]);
    assert_eq!(listed(&plan, "beta").len(), 1, "beta gets the release too");
    let public = site.public();
    for (rel, bytes) in &old {
        if rel.starts_with("1.0.0/") || rel == "keys.json" {
            assert!(public.get(rel) == Some(bytes), "{rel} changed");
        }
    }
    assert!(public.contains_key(&format!("1.1.0/{}.from-1.0.0.delta", targets()[0])));
    assert_eq!(site.private()[PENDING], EMPTY_RECORD);
    site.assert_verifies("download-migrated");
    site.assert_sibling();
}

#[test]
fn every_refusal_is_checked_by_its_message_and_leaves_the_store_as_it_was() {
    let site = Site::bare(2);
    let args = |rd: &Path, v: &str| -> Output { site.push_out(rd, v, &[]) };

    // No init yet: a release directory built from the fixture's documents only.
    let mut docs = BTreeMap::new();
    docs.insert(
        "keys.json".to_owned(),
        fs::read(site.origin.join("keys.json")).unwrap(),
    );
    let rd0 = site.f.release_dir("rd-first", &docs, "1.0.0");
    let err = assert_fails(&args(&rd0, "1.0.0"), 1, "push before init");
    assert!(err.contains("run `lunepack publish init` first"), "{err}");
    let err = assert_fails(&site.refresh(&[]), 1, "refresh before init");
    assert!(err.contains("run `lunepack publish init` first"), "{err}");
    assert!(!site.store.join("public").join(P).exists());
    assert!(!site.store.join("private").join(P).exists());

    // init: a dry run writes nothing; a second init finds the same documents and uploads nothing.
    let out = site.cmd("init", &["--release-dir", s(&site.origin), "--dry-run"]);
    assert_ok(&out, "init dry run");
    assert!(!site.store.join("public").join(P).exists());
    let out = site.cmd("init", &["--release-dir", s(&site.origin)]);
    assert_ok(&out, "init");
    let before = tree(&site.store);
    let out = site.cmd("init", &["--release-dir", s(&site.origin)]);
    assert_ok(&out, "second init");
    assert!(
        stdout(&out).contains("nothing to upload"),
        "{}",
        stdout(&out)
    );
    assert!(tree(&site.store) == before);

    site.publish("1.0.0");

    // A version a feed lists cannot be fetched again.
    let rd = site.f.dir.path().join("rd-again");
    let before = tree(&site.store);
    let out = site.fetch(&rd, "1.0.0");
    let err = assert_fails(&out, 1, "fetch a published version");
    assert!(err.contains("version 1.0.0 is already published"), "{err}");
    assert!(!rd.exists());

    // Missing store credentials are named, never shown; nothing is read.
    let out = site.f.push(
        &site.config,
        &site.f.dir.path().join("rd-1.0.0"),
        "1.0.0",
        &[],
        &[],
    );
    let err = assert_fails(&out, 1, "no credentials");
    assert!(
        err.contains("the environment variable HELLO_STORE_KEY"),
        "{err}"
    );
    assert!(stdout(&out).is_empty(), "{}", stdout(&out));

    // The commands that issue documents refuse SOURCE_DATE_EPOCH.
    let epoch = [("SOURCE_DATE_EPOCH", site.f.epoch.as_str())];
    let sign = site.sign();
    for command in [
        vec!["publish", "refresh", "--sign", &sign],
        vec!["publish", "init", "--release-dir", s(&site.origin)],
    ] {
        let mut all = vec!["--config", s(&site.config)];
        all.extend_from_slice(&command);
        all.extend_from_slice(&["--store-dir", s(&site.store)]);
        let err = assert_fails(&site.f.run_plain(&all, &epoch), 1, command[1]);
        assert!(err.contains("SOURCE_DATE_EPOCH is set"), "{err}");
    }
    let out = site.f.push(
        &site.config,
        &site.f.dir.path().join("rd-1.0.0"),
        "1.0.0",
        &["--store-dir", s(&site.store)],
        &epoch,
    );
    let err = assert_fails(&out, 1, "push with SOURCE_DATE_EPOCH");
    assert!(err.contains("SOURCE_DATE_EPOCH is set"), "{err}");
    assert!(tree(&site.store) == before);

    // The store moved after fetch: 1.2.0 is fetched, 1.1.0 is published, then 1.2.0 is pushed.
    let stale = site.prepare("1.2.0");
    site.publish("1.1.0");
    let before = tree(&site.store);
    let err = assert_fails(&args(&stale, "1.2.0"), 1, "the store changed");
    assert!(err.contains("the store changed since fetch"), "{err}");
    assert!(tree(&site.store) == before);

    // An object of the new version that differs from what the store holds is refused before any
    // write.
    let rd = site.prepare("1.3.0");
    let planted = site
        .store
        .join("public")
        .join(P)
        .join("1.3.0")
        .join(format!("{}.pack", targets()[0]));
    fs::create_dir_all(planted.parent().unwrap()).unwrap();
    fs::write(&planted, b"not the pack").unwrap();
    let before = tree(&site.store);
    let err = assert_fails(&args(&rd, "1.3.0"), 1, "a differing object");
    assert!(
        err.contains("the store already holds other bytes at"),
        "{err}"
    );
    assert!(tree(&site.store) == before);
    fs::remove_file(&planted).unwrap();
    assert_ok(
        &args(&rd, "1.3.0"),
        "push after the planted object is removed",
    );

    // A target the release lacks, and arguments that are not a usage.
    let rd = site.prepare("1.4.0");
    let before = tree(&site.store);
    let out = site.push_out(&rd, "1.4.0", &["--require-targets", "macos-aarch64"]);
    let err = assert_fails(&out, 1, "a missing target");
    assert!(err.contains("no macos-aarch64 target"), "{err}");
    assert_fails(&args(&rd, "1.4"), 2, "a version that is not SemVer");
    assert_fails(
        &site.push_out(&rd, "1.4.0", &["--require-targets", "not-a-target"]),
        2,
        "a target id that is none",
    );
    assert!(tree(&site.store) == before);
    site.assert_sibling();
}

#[test]
fn the_output_scan_catches_a_planted_secret_line() {
    let site = Site::bare(10);
    let planted = [
        site.access.clone(),
        site.secret.clone(),
        "-----BEGIN PRIVATE".to_owned(),
    ];
    let secrets: Vec<&[u8]> = site.f.secrets.iter().map(Vec::as_slice).collect();
    for line in &planted {
        let output = Output {
            status: std::process::ExitStatus::default(),
            stdout: format!("read: hello/keys.json found {line}\n").into_bytes(),
            stderr: Vec::new(),
        };
        let hit = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            assert_no_secrets(&output, &secrets)
        }));
        assert!(hit.is_err(), "the scan misses a planted line");
    }
    let clean = Output {
        status: std::process::ExitStatus::default(),
        stdout: b"read: hello/keys.json found\n".to_vec(),
        stderr: Vec::new(),
    };
    assert_no_secrets(&clean, &secrets);
}
